const sorters={recent:(a,b)=>a.posted-b.posted,'price-asc':(a,b)=>a.price-b.price,'price-desc':(a,b)=>b.price-a.price,nearest:(a,b)=>a.distance-b.distance,savings:(a,b)=>(b.retail-b.price)/b.retail-(a.retail-a.price)/a.retail};
const limit=value=>{if(value===null||value==='')return Infinity;const n=Number(value);return Number.isNaN(n)||n<0?null:n;};
export function filterMarketplace(params){
 const max=limit(params.get('budget')),miles=limit(params.get('distance'));if(max===null||miles===null)return [];
 const q=(params.get('q')||'').toLowerCase().trim(),platform=params.get('platform'),category=params.get('category');
 const results=marketplaceListings.filter(p=>p.price<=max&&p.distance<=miles&&(!platform||platform==='all'||p.platform===platform)&&(!category||category==='all'||p.category===category)&&(params.get('available')!=='true'||p.status==='Available')&&(params.get('portable')!=='true'||p.portable)&&`${p.name} ${p.condition} ${p.area} ${p.category}`.toLowerCase().includes(q));
 return results.sort(sorters[params.get('sort')]||sorters.recent);
}
